import{z as B,x as A,o,c as p,q as r,j as t,D as n,d as E,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"存款保险","description":"","frontmatter":{"title":"存款保险","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/deposit-insurance.md","filePath":"econ/deposit-insurance.md","lastUpdated":1791413859000}'),d={name:"econ/deposit-insurance.md"};function D(m,a,c,u,h,f){const i=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=r('<h1 id="存款保险" tabindex="-1">存款保险 <a class="header-anchor" href="#存款保险" aria-label="Permalink to &quot;存款保险&quot;">​</a></h1><div class="epigraph"><p>保险可以删掉挤兑均衡；同一张保单也把资产风险从存款人转到保险基金。</p><footer>—— Diamond and Dybvig, Journal of Political Economy 1983，保险与暂停兑付；Keeley, Deposit Insurance, Risk, and Market Power in Banking, American Economic Review 1990</footer></div><p><a href="/econ/fire-sales">上一课</a>（火线出售）。传染已经说明：删掉单家坏均衡，不等于删掉银行间通道上的损失。本课缺口是保险本身：它如何停挤兑，以及停掉之后激励移到哪里。不重写 Diamond–Dybvig 的双均衡证明，不重画 Allen–Gale 的网络。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1983 年正文已经把活期存款写成保险合同，附录式的政策含义是：政府保险或暂停兑付可以去掉坏均衡——耐心者不必排队，因为 \\(t=2\\) 的支付被保住。若这句话完整，保险是纯福利改进。缺口是另一面：保的是面值，不是资产质量。存款人不再给银行的风险定价，股东持有一个对保险基金的看跌期权。竞争若再削掉特许权价值，期权会被更用力地行使。</p><p>Keeley（1990）把这收成可观察的替换：特许权价值高时，银行珍惜牌照，少用保险期权；放松进入、利差变薄之后，同一保险下风险上升。缺口不是「要不要保险」，而是：停挤兑与风险转移必须写成同一张保单的两面。</p><p><span class="marginnote">暂停兑付删坏均衡，但不把信用风险转给财政；保险把信用风险转走。Diamond–Dybvig 的标题把保险与流动性写成一件家具，没有把看跌期权写进效用函数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先取 1983 年的政策实验。保险保证耐心者在 \\(t=2\\) 仍按合同受偿（或急躁者按 \\(r_1\\) 受偿），于是加入挤兑队列不再是最优反应。暂停兑付在急躁者份额被满足后关门，同样保护剩余资产。两者都改博弈，都不给银行送股本——模型里还没有<a href="/econ/basel-capital">资本</a>。</p><p>再把资产选择加回去。若保险保费与风险无关（平坦保费），股东的收益对上行开放、对下行截断。这是<a href="/econ/moral-hazard">道德风险</a>在被保险负债上的版本：隐藏行动是把贷款换成更肥尾的项目。特许权价值——未来租金的现值——是抵押品：它提高失败的私人成本，部分抵消期权。Keeley 的比较静态是：市场势力下降 ⇒ 特许权下降 ⇒ 同一保险下资产风险上升。</p><p><span class="marginnote">「看跌期权」翻译成日常话：一份「跌了有人赔」的合同。股东把银行资产换得越波动，这份合同越值钱，而亏的部分由保险基金付账——相当于拿别人的钱去赌，赢了归自己，输了有人兜底。</span></p>',11)),(o(),t(s,null,{default:n(()=>[l(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E5%AD%98%E6%AC%BE%E4%BF%9D%E9%99%A9%22%5D%20--%3E%20NORUN%5B%22%E8%80%90%E5%BF%83%E8%80%85%E4%B8%8D%E5%BF%85%E8%B7%91%3A%20%E5%9D%8F%E5%9D%87%E8%A1%A1%E6%B6%88%E5%A4%B1%22%5D%0A%20%20INS%20--%3E%20PUT%5B%22%E5%AF%B9%E4%BF%9D%E9%99%A9%E5%9F%BA%E9%87%91%E7%9A%84%E7%9C%8B%E8%B7%8C%22%5D%0A%20%20PUT%20--%3E%20FLAT%5B%22%E5%B9%B3%E5%9D%A6%E4%BF%9D%E8%B4%B9%3A%20%E9%A3%8E%E9%99%A9%E4%B8%8D%E5%85%A5%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20CHAR%5B%22%E7%89%B9%E8%AE%B8%E6%9D%83%E4%BB%B7%E5%80%BC%22%5D%20--%3E%20PUT%0A%20%20FLAT%20--%3E%20SHIFT%5B%22%E9%A3%8E%E9%99%A9%E8%BD%AC%E7%A7%BB%E5%88%B0%E5%9F%BA%E9%87%91%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"「特许权价值」可以想象成一张出租车牌照：牌照越值钱，司机越不敢闯红灯——被吊销的损失不只是罚款，而是整张牌照的未来收入。银行同理：未来利润越厚，越不敢拿牌照去赌高风险项目。")],-1)),a[4]||(a[4]=e("p",null,"风险调整保费、共同保险、覆盖上限，都是把期权费部分写回存款人或股东。本课只钉逻辑，不列某国保险基金的费率表。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[E("机制是信念与激励的分工。保险改变耐心者对 \\(t=2\\) 的信念，战略互补被切断，挤兑与由挤兑导入的"),e("a",{href:"/econ/bank-contagion"},"传染"),E("在被覆盖的负债上减弱。同一切断使市场纪律减弱：未被覆盖的批发债权仍会跑，被覆盖的零售不再给风险定价。于是风险被赶到保险边界之内的资产与负债结构上。")],-1)),a[7]||(a[7]=e("p",null,"银行间存款往往不在零售保险里。保险可以稳住房间里的挤兑，同时把损失留给未保险的互存——传染课的边并未被自动删掉。这不是保险「失败」，是覆盖集与网络不是同一张图。",-1)),(o(),t(s,null,{default:n(()=>[l(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20COV%5B%22%E4%BF%9D%E9%99%A9%E8%A6%86%E7%9B%96%E9%9B%86%E5%88%92%E7%95%8C%22%5D%20--%3E%20RET%5B%22%E9%9B%B6%E5%94%AE%E5%AD%98%E6%AC%BE%3A%20%E5%9C%A8%E8%A6%86%E7%9B%96%E5%86%85%22%5D%0A%20%20COV%20--%3E%20WHL%5B%22%E6%89%B9%E5%8F%91%E4%B8%8E%E9%93%B6%E8%A1%8C%E9%97%B4%E5%80%BA%E6%9D%83%3A%20%E5%9C%A8%E8%A6%86%E7%9B%96%E5%A4%96%22%5D%0A%20%20RET%20--%3E%20NR%5B%22%E5%AD%98%E6%AC%BE%E4%BA%BA%E4%B8%8D%E5%86%8D%E7%9B%AF%E9%A3%8E%E9%99%A9%22%5D%0A%20%20WHL%20--%3E%20DIS%5B%22%E5%B8%82%E5%9C%BA%E7%BA%AA%E5%BE%8B%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20DIS%20--%3E%20WR%5B%22%E6%89%B9%E5%8F%91%E6%8C%A4%E5%85%91%E9%80%9A%E9%81%93%E4%BF%9D%E7%95%99%22%5D%0A%20%20AR%5B%22%E9%93%B6%E8%A1%8C%E8%B5%84%E4%BA%A7%E9%A3%8E%E9%99%A9%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20WHL%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">覆盖上限举个数：若上限是 50 万，存 40 万的人全额受保、不必看银行脸色；存 500 万的人有 450 万暴露在外——他会盯着银行的资产质量，随时准备搬钱。划界就是把「盯风险」的任务派回给大储户与机构。</span></p><h3 id="平坦保费就是看跌期权的价格为零" tabindex="-1">平坦保费就是看跌期权的价格为零 <a class="header-anchor" href="#平坦保费就是看跌期权的价格为零" aria-label="Permalink to &quot;平坦保费就是看跌期权的价格为零&quot;">​</a></h3><p>若保费不随资产风险或杠杆变动，看跌的价格被错标。股东的最优是增加期权的标的波动，直到特许权或监管资本挡住。资本监管后置，正是因为保险已经先改了激励。不要把后课的巴塞尔提前写成保险的替代：一个删坏均衡，一个写亏损顺序。</p><p><span class="marginnote">覆盖上限把大额债权人留在市场纪律里，也把批发挤兑留在系统里。保险从来不是「所有负债都按面值保」；边界划在哪里，决定哪一种跑仍会发生。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把保险写成「政府给银行资本」。资本是可核销的损失吸收；保险是对特定负债的或有支付。也不要把 Keeley 读成「竞争有害」：竞争削特许权，是在<strong>已有平坦保险</strong>的前提下放大期权；没有保险时，竞争约束的是另一套定价。</p><p>本课不写最后贷款人的抵押规则，不写太大而不能倒。窗口针对流动性，保险针对面值信念；对股东的隐担保是再下一层，会把看跌从保险基金扩到全体债权人。那一层在 <a href="/econ/too-big-to-fail">TBTF</a>。</p><p>后课默认：保险停挤兑，代价是风险从存款人转到基金；平坦保费加低特许权使转移最大。未保险的银行间债权仍可传染。下一课回到准备金与内生货币，不再把保险当货币创造。</p><p>暂停与保险都能删坏均衡，信用风险的归宿不同。覆盖集不是网络图。</p><p>不要用「道德风险」取消 1983 年的保险结论。两句话必须同时保留。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保险或暂停可以删掉 Diamond–Dybvig 坏均衡，不是给银行送股本。</li><li>平坦保费把资产风险写成对基金的看跌；特许权价值是部分抵押。</li><li>覆盖集与银行间网络不一致时，传染通道仍在。</li><li>出处：Diamond and Dybvig, <em>JPE</em> 1983；Keeley, <em>AER</em> 1990。</li></ul>',12))])}const C=B(d,[["render",D]]);export{b as __pageData,C as default};
